#include <stdio.h>
#include <stdlib.h>

// Comparador para ordenar em ordem decrescente
int cmp(const void *a, const void *b) {
    long long x = *(long long*)a;
    long long y = *(long long*)b;
    if (x > y) return -1;
    if (x < y) return 1;
    return 0;
}

int main(void) {
    int N, K;
    scanf("%d %d", &N, &K);

    long long *a = (long long*)malloc((N + 1) * sizeof(long long));
    long long *b = (long long*)malloc((N + 1) * sizeof(long long));
    long long *bonus = (long long*)malloc(N * sizeof(long long));

    for (int i = 1; i <= N; i++) {
        scanf("%lld", &a[i]);
    }
    for (int i = 1; i <= N; i++) {
        scanf("%lld", &b[i]);
    }

    long long base = 0;
    for (int i = 1; i <= N; i++) {
        if (a[i] >= b[i]) {
            base += a[i] - b[i];
            bonus[i - 1] = b[i];
        } else {
            bonus[i - 1] = a[i];
        }
    }

    // Ordena os bônus em ordem decrescente
    qsort(bonus, N, sizeof(long long), cmp);

    // Podemos escolher até K sílabas para zerar e 1 sílaba para ser a última (L)
    int M = K + 1;
    if (M > N) M = N;

    for (int i = 0; i < M; i++) {
        base += bonus[i];
    }

    printf("%lld\n", base);

    free(a);
    free(b);
    free(bonus);
    return 0;
}
